// Generated by build.ts from the installed @squonk/ui: its dist/stories
// bundle, plus the library components the page's controls are made of (typed
// here only as far as the page uses them, so this package needn't depend on
// the library's types).
declare module "virtual:squonk-ui-stories" {
  import type { ChangeEvent, ComponentType, Context, InputHTMLAttributes, ReactNode, TextareaHTMLAttributes } from "react";

  /** One story as dist/stories/stories.mjs registers it. */
  export type StoryRecord = {
    id: string;
    title: string;
    name: string;
    /** Why the story can't be shown outside Storybook, when it can't. */
    unavailable?: string;
    /** The stories file's default export (CSF meta). */
    meta: Record<string, unknown>;
    /** The named export: a CSF3 object, or a function. */
    story: unknown;
    /** argTypes inferred from the meta's component props. */
    argTypes: Record<string, Record<string, unknown>>;
  };

  export const stories: StoryRecord[];
  export const StoryArgsContext: Context<unknown>;
  export const SquonkThemeProvider: ComponentType<{
    mode: "light" | "dark";
    primitives?: Record<string, unknown>;
    roleBindings?: Record<string, string | { light: string; dark: string }>;
    colorBindings?: Record<string, string>;
    addedColorPrimitives?: Record<string, { light: string; dark: string }>;
    withGlobalStyles?: boolean;
    children?: ReactNode;
  }>;

  /** One of the docs' example themes. */
  export type ExampleTheme = {
    id: string;
    name: string;
    description: string;
    primitives: Record<string, unknown>;
    roleBindings: Record<string, string | { light: string; dark: string }>;
  };
  export const EXAMPLE_THEMES: ExampleTheme[];
  /** The Google Fonts families an example theme uses. */
  export const themeFonts: (theme: Pick<ExampleTheme, "primitives">) => string[];
  /** The library's theme document parser, as the Storybook theme panel imports with. */
  export const parseThemeDocument: (json: string) => { ok: true; doc: Record<string, unknown> } | { ok: false; error: string };

  type Option = { value: string; label: string };
  type Field = { label?: string; helperText?: string; error?: string };
  export const Button: ComponentType<{ variant?: "primary" | "secondary" | "ghost"; onClick?: () => void; disabled?: boolean; children?: ReactNode }>;
  export const Presentation: ComponentType<{ register: "compact" | "default" | "large" | "hero"; children?: ReactNode }>;
  export const Switch: ComponentType<{ label?: ReactNode; helperText?: string; checked?: boolean; onChange?: (checked: boolean) => void }>;
  export const TextField: ComponentType<Field & Omit<InputHTMLAttributes<HTMLInputElement>, "size" | "onChange"> & { onChange?: (event: ChangeEvent<HTMLInputElement>) => void }>;
  export const Textarea: ComponentType<Field & Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, "onChange"> & { onChange?: (event: ChangeEvent<HTMLTextAreaElement>) => void }>;
  export const Select: ComponentType<Field & { options: Option[]; value?: string; placeholder?: string; clearable?: boolean; onChange?: (value: string) => void }>;
  export const RadioGroup: ComponentType<{ name: string; legend?: string; helperText?: string; direction?: "row" | "column"; options: Option[]; value?: string; onChange?: (value: string) => void }>;
}
